'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),{tree,hash,fail}=require('./codeAssistant.cjs');
function createBuilder({config,dataDir,engine}){const dist=path.join(config.appDir,'dist'),store=path.join(dataDir,'deployments.json');let rows=[];try{rows=JSON.parse(fs.readFileSync(store,'utf8'))}catch(e){if(e.code!=='ENOENT')throw e}const save=()=>{fs.mkdirSync(dataDir,{recursive:true});fs.writeFileSync(store+'.tmp',JSON.stringify(rows));fs.renameSync(store+'.tmp',store)};
 const sourceHashes=()=>Object.fromEntries(tree(config.sourceRoot).map(f=>[f.path,hash(fs.readFileSync(path.join(config.sourceRoot,f.path)))]));
 function build(pid){const p=engine.project(pid);if(p.root!==fs.realpathSync(config.sourceRoot))throw fail('Nút này chỉ dành cho mã nguồn giao diện MUSE');return engine.launch(pid,'build-muse',async(task,signal,update)=>{const before=sourceHashes(),esbuild=require(path.join(config.sourceRoot,'node_modules/esbuild')),buildId=crypto.randomUUID(),name='muse-code-'+buildId,folder=path.join(dist,'assets',name),prefix='/assets/'+name+'/';fs.mkdirSync(folder,{recursive:true});update({phase:'Đang build giao diện MUSE',log:'Đang biên dịch ảnh, workspace và trợ lý…\n'});const base={bundle:true,minify:true,external:['/assets/*'],logLevel:'silent'};await esbuild.build({...base,entryPoints:[path.join(p.root,'image-studio-v2.jsx')],format:'iife',globalName:'MondayStudioV2',jsxFactory:'M.createElement',jsxFragment:'M.Fragment',alias:{react:path.join(p.root,'react-host-shim.js')},outfile:path.join(folder,'image-studio.js')});for(const [entry,out] of [['src/space.jsx','monday-space.js'],['src/experience.jsx','monday-experience.js']])await esbuild.build({...base,entryPoints:[path.join(p.root,entry)],format:'esm',outfile:path.join(folder,out)});if(signal.aborted)throw fail('Đã dừng build');if(JSON.stringify(before)!==JSON.stringify(sourceHashes()))throw fail('Mã nguồn đã đổi trong lúc build, hãy build lại',409);
 const index=fs.readFileSync(path.join(dist,'index.html'),'utf8'),match=index.match(/<script[^>]+src=["'](\/assets\/[^"']+)["']/);if(!match)throw fail('Không xác định được bundle của app');const hostURL=match[1].split('?')[0];if(hostURL.includes('..')||!hostURL.endsWith('/host-preview.js'))throw fail('Bundle host không nằm trong vị trí quản lý');const oldPrefix=hostURL.slice(0,hostURL.lastIndexOf('/')+1);let host=fs.readFileSync(path.join(dist,hostURL.slice(1)),'utf8'),a=host.indexOf('var MondayStudioV2='),b=host.indexOf('function MondayImageStudio',a);if(a<0||b<a)throw fail('Không xác định được khối giao diện ảnh');host=host.slice(0,a)+fs.readFileSync(path.join(folder,'image-studio.js'),'utf8')+';'+host.slice(b);host=host.split(oldPrefix).join(prefix);fs.writeFileSync(path.join(folder,'host-preview.js'),host);
 const exp=path.join(folder,'monday-experience.js');fs.writeFileSync(exp,fs.readFileSync(exp,'utf8').replace(/\/assets\/(?:space|polished-20261028|coding-20261028)\/monday-space\.js\?[^"'\s]+/g,prefix+'monday-space.js?v='+buildId));fs.copyFileSync(path.join(p.root,'src/simpleStudio.css'),path.join(folder,'simpleStudio.css'));
 let ready=index.split(oldPrefix).join(prefix);if(fs.existsSync(path.join(folder,'monday-experience.css'))&&!ready.includes(prefix+'monday-experience.css'))ready=ready.replace('</head>','<link rel="stylesheet" href="'+prefix+'monday-experience.css">\n</head>');fs.writeFileSync(path.join(folder,'preview.html'),ready);const assets=fs.readdirSync(folder).filter(n=>/\.(?:js|css|html)$/.test(n)).map(n=>({name:n,hash:hash(fs.readFileSync(path.join(folder,n)))}));const row={id:buildId,projectId:pid,createdAt:Date.now(),status:'staged',folder,prefix,sourceHashes:before,assets,index:ready,previousIndex:null,previewURL:prefix+'preview.html'};rows.push(row);save();return {buildId,previewURL:row.previewURL,reply:'Build thành công. Có thể xem thử rồi nạp vào app.',phase:'Bản dựng sẵn sàng',log:'Build thành công: '+assets.map(a=>a.name).join(', ')}})}
 function activate(id){const d=rows.find(x=>x.id===id);if(!d||d.status!=='staged')throw fail('Bản dựng không còn ở trạng thái chờ',409);if(engine.tasks(d.projectId).some(t=>t.status==='running'))throw fail('Dự án đang bận',409);if(JSON.stringify(d.sourceHashes)!==JSON.stringify(sourceHashes()))throw fail('Mã nguồn đã thay đổi sau bản dựng, hãy build lại',409);for(const f of d.assets)if(hash(fs.readFileSync(path.join(d.folder,f.name)))!==f.hash)throw fail('Tệp bản dựng đã thay đổi',409);const file=path.join(dist,'index.html');d.previousIndex=fs.readFileSync(file,'utf8');d.newHash=hash(d.index);d.status='active';for(const old of rows)if(old.id!==id&&old.status==='active')old.status='previous';save();fs.writeFileSync(file+'.code.tmp',d.index);fs.renameSync(file+'.code.tmp',file);return {success:true,reload:true,id}}
 function rollback(id){const d=rows.find(x=>x.id===id);if(!d||d.status!=='active'||!d.previousIndex)throw fail('Không có bản trước để khôi phục',409);const file=path.join(dist,'index.html');if(hash(fs.readFileSync(file))!==d.newHash)throw fail('Giao diện hiện tại đã đổi, không ghi đè bản khác',409);fs.writeFileSync(file+'.code.tmp',d.previousIndex);fs.renameSync(file+'.code.tmp',file);d.status='rolled-back';const restored=rows.find(x=>x.newHash===hash(d.previousIndex));if(restored)restored.status='active';save();return {success:true,reload:true}}
 return {build,activate,rollback,list:()=>rows.map(({id,projectId,createdAt,status,previewURL})=>({id,projectId,createdAt,status,previewURL}))}}
module.exports={createBuilder};
